#include "civ5/runtime/bnw_notification_cleanup.hpp"
#include "civ5/runtime/file_identity.hpp"
#include <algorithm>
#include <climits>
#include <set>
#include <stdexcept>
namespace civ5::runtime {
namespace {
constexpr auto bnw=saves::GameStateLayout::expansion2_version1;
constexpr std::array<std::uint32_t,20> persistent_types{{
#include "bnw_notification_persistent_types.inc"
}};
constexpr std::array<std::uint32_t,4> connection_types{{
#include "bnw_notification_connections_types.inc"
}};
void need(bool v,const char *why){if(!v)throw std::runtime_error(why);}
std::string_view name(const char *v){return v?std::string_view(v):std::string_view();}
std::int64_t &field(saves::PlayerAdministrationRecord &r,std::string_view n){saves::NamedSaveInteger *out=nullptr;for(auto &f:r.fields)if(name(f.name)==n){need(!out,"Duplicate notification native field");out=&f;}need(out,"Missing notification native field");return out->value;}
std::int64_t field(const saves::PlayerAdministrationRecord &r,std::string_view n){return field(const_cast<saves::PlayerAdministrationRecord&>(r),n);}
std::int32_t native(std::int64_t v){need(v>=INT32_MIN && v<=INT32_MAX,"Notification operand exceeds native int");return static_cast<std::int32_t>(v);}
std::int64_t core(const saves::PlayerCoreObservation &c,std::string_view n){need(c.layout==bnw,"Notification native player core layout unknown");const saves::PlayerCoreField *out=nullptr;for(const auto &f:c.fields)if(name(f.name)==n){need(!out && f.values.size()==1,"Unknown notification player scalar");out=&f;}need(out && (out->encoding==saves::PlayerCoreEncoding::i32 || out->encoding==saves::PlayerCoreEncoding::boolean),"Missing/wrong native notification player scalar");return native(out->values[0]);}
const saves::PlayerAdministrationRecord &ring(const LiveSessionState &s,std::int64_t p){need(p>=0 && p<64 && s.world.all_players,"Notification actor invalid");const auto &a=s.world.all_players->players.at(p).administration;need(a.layout==bnw && a.blocks.size()==3 && name(a.blocks[0].name)=="notifications","Notification object Read schema unknown");return a.blocks[0];}
saves::PlayerAdministrationRecord &ring(LiveSessionState &s,std::int64_t p){return const_cast<saves::PlayerAdministrationRecord&>(ring(static_cast<const LiveSessionState&>(s),p));}
std::string string_field(const saves::PlayerAdministrationRecord &r,std::string_view n){const saves::PlayerAdministrationBlob *out=nullptr;for(const auto &b:r.blobs)if(name(b.name)==n){need(!out,"Duplicate notification string");out=&b;}need(out,"Notification string missing");const auto end=std::find(out->bytes.begin(),out->bytes.end(),0);return std::string(out->bytes.begin(),end);}
BnwNotificationUiEntry entry(const saves::PlayerAdministrationRecord &row,std::int64_t player,std::uint64_t slot){const auto type=field(row,"m_eNotificationType_bits");need(type>=0 && type<=UINT32_MAX,"Notification type bits unknown");return {player,native(field(row,"m_iLookupIndex")),slot,static_cast<std::uint32_t>(type),string_field(row,"m_strMessage"),string_field(row,"m_strSummary"),native(field(row,"m_iX")),native(field(row,"m_iY")),native(field(row,"m_iGameDataIndex")),native(field(row,"m_iExtraGameData")),native(field(row,"m_iTurn"))};}
std::vector<std::size_t> active(const saves::PlayerAdministrationRecord &r,std::int64_t player) {
 const auto has=field(r,"has_notifications");need(has==0 || has==1,"Notification object presence unknown");if(!has){need(r.fields.size()==1 && r.children.empty(),"Null notification object has slots");return {};}
 need(field(r,"version")==2 && field(r,"m_ePlayer")==player && r.fields.size()==6 && r.children.size()==100,"Notification native owner/version/100-slot schema differs");
 const auto begin=native(field(r,"m_iNotificationsBeginIndex")),end=native(field(r,"m_iNotificationsEndIndex")),next=native(field(r,"m_iCurrentLookupIndex"));need(begin>=0 && begin<100 && end>=0 && end<100 && next>=0,"Notification native ring cursors invalid");
 for(std::size_t n=0;n<100;++n){const auto &row=r.children[n];need(name(row.name)=="notification" && row.index==n && row.fields.size()==11 && row.blobs.size()==2 && row.children.empty() && row.arrays.empty(),"Notification slot shape unknown");need(field(row,"m_bDismissed")==0 || field(row,"m_bDismissed")==1,"Notification dismissed bit unknown");(void)entry(row,player,n);}
 std::vector<std::size_t> out;std::set<std::int64_t> lookups;
 for(int cursor=begin;cursor!=end;cursor=(cursor+1)%100){const auto &row=r.children.at(cursor);const auto lookup=native(field(row,"m_iLookupIndex"));need(lookup>=0 && lookup<next && lookups.insert(lookup).second && field(row,"m_ePlayerID")==player,"Notification live lookup/player identity invalid");if(!field(row,"m_bDismissed"))out.push_back(cursor);}
 return out;
}
void number(std::vector<std::uint8_t>&b,std::uint64_t v){for(int n=0;n<8;++n)b.push_back(v>>(8*n));}
void text(std::vector<std::uint8_t>&b,std::string_view s){number(b,s.size());b.insert(b.end(),s.begin(),s.end());}
void raw_record(std::vector<std::uint8_t>&b,const saves::PlayerAdministrationRecord &r){text(b,name(r.name));number(b,r.index);number(b,r.fields.size());for(const auto &f:r.fields){text(b,name(f.name));number(b,f.value);}number(b,r.blobs.size());for(const auto &blob:r.blobs){text(b,name(blob.name));number(b,blob.bytes.size());b.insert(b.end(),blob.bytes.begin(),blob.bytes.end());}number(b,r.children.size());for(const auto &c:r.children)raw_record(b,c);}
void refresh(LiveSessionState &s,std::int64_t player){auto &context=s.notification_load_transients;context.players.at(player).active_undismissed=active(ring(s,player),player);context.external_update_pending=false;for(const auto &[id,p]:context.players)for(auto slot:p.active_undismissed)context.external_update_pending=context.external_update_pending || p.slots.at(slot).needs_broadcast;}
void validate(const LiveSessionState &s,const BnwNotificationCleanupOwner &owner,const content::RulesDatabase &rules){need(owner.map_guid()==s.world.map_header.guid && owner.epoch()==bnw_notification_epoch(s,owner.identity(),rules),"Notification retained owner has stale raw ring/flags/load identity");}
}
bool bnw_notification_type_end_turn_expired(std::uint32_t type,std::optional<std::int32_t> specific_turn,std::int32_t game_turn){if(std::find(persistent_types.begin(),persistent_types.end(),type)!=persistent_types.end())return false;if(std::find(connection_types.begin(),connection_types.end(),type)!=connection_types.end() && specific_turn && *specific_turn==game_turn)return false;return true;}
std::int32_t bnw_notification_game_turn_active_count(const LiveSessionState &s){need(s.world.all_players && s.world.all_players->layout==bnw && s.world.all_players->players.size()==64,"getNumGameTurnActive missing native64 roster");std::int32_t count=0;for(const auto &p:s.world.all_players->players){const auto alive=core(p.core,"m_bAlive"),turn=core(p.core,"m_bTurnActive");need((alive==0 || alive==1) && (turn==0 || turn==1),"getNumGameTurnActive unknown native bool");if(alive && turn)++count;}return count;}
std::string bnw_notification_epoch(const LiveSessionState &s,const SessionCheckpointIdentity &identity,const content::RulesDatabase &rules) {
 need(s.setup.profile==content::TechnologyProfile::bnw && s.world.game_state.layout==bnw && s.world.all_players && s.world.all_players->layout==bnw && s.world.all_players->players.size()==64 && s.world.all_players->context.player_count==64 && s.world.pregame && s.world.pregame->layout==bnw && identity.payload_sha256.size()==64 && identify_bytes(rules.gameplay_fingerprint_data()).sha256==identity.rules_sha256,"Notification source/rules/native roster unknown");
 need(s.setup.game_type==0 && s.world.pregame->archive.integers.at("game_type")==0,"Notification cleanup supports ordinary SP source predicate only");need(s.setup.game_turn>=0 && s.setup.game_turn<=INT32_MAX && s.world.pregame->archive.integers.at("game_turn")==s.setup.game_turn,"Notification source gameTurn unknown");
 need(s.notification_load_transients.current,"Notification retained Read/lifecycle flags unknown");std::vector<std::uint8_t>b;text(b,identity.payload_sha256);text(b,identity.rules_sha256);b.insert(b.end(),s.world.map_header.guid.begin(),s.world.map_header.guid.end());number(b,s.setup.game_turn);std::size_t objects=0;
 for(std::size_t n=0;n<64;++n){const auto &p=s.world.all_players->players[n];need(p.index==n && p.saved_player_id==static_cast<std::int64_t>(n) && core(p.core,"m_eID")==static_cast<std::int64_t>(n),"Notification native GetPlayer identity differs");const auto &r=ring(s,n);const auto positions=active(r,n);number(b,n);raw_record(b,r);
  const bool has=field(r,"has_notifications")!=0;if(!has){need(!s.notification_load_transients.players.contains(n),"Null native notification object has retained flags");continue;}++objects;
  const auto f=s.notification_load_transients.players.find(n);need(f!=s.notification_load_transients.players.end() && f->second.active_undismissed==positions,"Notification actual ring/retained active positions differ");for(const auto &slot:f->second.slots){number(b,slot.needs_broadcast);number(b,slot.wait_extra_turn);}number(b,positions.size());for(auto slot:positions)number(b,slot);
 }
 need(objects==s.notification_load_transients.players.size(),"Notification flags object roster differs");number(b,s.notification_load_transients.external_update_pending);return identify_bytes(b).sha256;
}
BnwNotificationReadReceipt attest_bnw_notification_read_context(const LiveSessionState &s,const saves::SavedSession &source,const SessionCheckpointIdentity &identity,const content::RulesDatabase &rules){need(source.source.container==saves::SaveContainerKind::civ5 && identify_bytes(source.source.bytes).sha256==identity.payload_sha256 && source.snapshot.map_header.guid==s.world.map_header.guid,"Notification import/load receipt identity unknown");const auto expected=rebuild_bnw_notification_load_transients(s,source,identity);need(s.notification_load_transients.current && expected.current && s.notification_load_transients.players==expected.players && s.notification_load_transients.external_update_pending==expected.external_update_pending,"Notification Read receipt needs actual matching source-derived flags");return BnwNotificationReadReceipt(identity,s.world.map_header.guid,bnw_unit_order_world_revision(s,identity,rules),bnw_notification_epoch(s,identity,rules));}
BnwNotificationCleanupOwner bind_bnw_notification_cleanup_read(const LiveSessionState &s,BnwNotificationReadReceipt &&receipt,const content::RulesDatabase &rules){need(!receipt.used_ && receipt.guid_==s.world.map_header.guid && receipt.load_world_==bnw_unit_order_world_revision(s,receipt.identity_,rules) && receipt.epoch_==bnw_notification_epoch(s,receipt.identity_,rules),"Notification cold bind missing/used/stale actual Read receipt");receipt.used_=true;return BnwNotificationCleanupOwner(receipt.identity_,receipt.guid_,receipt.epoch_);}
BnwNotificationUiOwner start_bnw_notification_ui_client(const LiveSessionState &s,const BnwNotificationCleanupOwner &owner,const content::RulesDatabase &rules){validate(s,owner,rules);BnwNotificationUiOwner out(owner.identity(),owner.map_guid(),owner.epoch());for(const auto &[player,f]:s.notification_load_transients.players)for(auto slot:f.active_undismissed){auto e=entry(ring(s,player).children.at(slot),player,slot);need(out.entries_.emplace(std::pair{player,e.lookup},std::move(e)).second,"Duplicate actual notification client entry");}return out;}
void apply_bnw_notification_ui_batch(const LiveSessionState &s,BnwNotificationUiOwner &owner,const content::RulesDatabase &rules,const BnwNotificationUiBatch &batch){need(owner.identity_.payload_sha256==batch.identity.payload_sha256 && owner.identity_.rules_sha256==batch.identity.rules_sha256 && owner.map_guid_==batch.map_guid && batch.map_guid==s.world.map_header.guid && batch.before_epoch==owner.epoch_ && batch.after_epoch==bnw_notification_epoch(s,owner.identity_,rules) && batch.expected_client_revision==owner.client_revision_ && owner.client_revision_<UINT64_MAX,"RemoveNotification actual client feed stale/identity mismatch");auto d=owner;for(const auto &remove:batch.removals){const auto &r=ring(s,remove.player);need(field(r,"has_notifications")==1 && remove.slot<100,"RemoveNotification refers to absent native object/slot");const auto &row=r.children.at(remove.slot);const auto actual=entry(row,remove.player,remove.slot);need(actual.lookup==remove.lookup && field(row,"m_bDismissed")==1,"RemoveNotification differs from actual dismissed native lookup");const auto ui=d.entries_.find({remove.player,remove.lookup});need(ui!=d.entries_.end() && ui->second==actual,"RemoveNotification actual client entry differs from native data");d.entries_.erase(ui);d.received_removals_.push_back(remove);}d.epoch_=batch.after_epoch;++d.client_revision_;owner=std::move(d);}
class BnwNotificationCleanupOperations {
 public:
 static BnwNotificationCleanupExecution cleanup(const LiveSessionState &s,const BnwNotificationCleanupOwner &owner,const BnwNotificationUiOwner &client,const content::RulesDatabase &rules,std::int64_t player){BnwNotificationCleanupExecution out;try{validate(s,owner,rules);need(client.epoch()==owner.epoch(),"Cleanup has stale actual notification client");auto d=std::make_unique<BnwNotificationCleanupDraft>(BnwNotificationCleanupDraft{s,owner,client,{},{},{},0});need(owner.operations_<UINT64_MAX,"Notification operation counter exhausted");d->batch={owner.identity(),owner.map_guid(),owner.epoch(),"",client.client_revision(),{}};
   auto &r=ring(d->state,player);d->completed_steps.push_back(BnwNotificationCleanupStep::get_notifications);
   if(field(r,"has_notifications")){const auto begin=native(field(r,"m_iNotificationsBeginIndex")),end=native(field(r,"m_iNotificationsEndIndex"));for(int cursor=begin;cursor!=end;cursor=(cursor+1)%100){d->completed_steps.push_back(BnwNotificationCleanupStep::ring_scan);auto &row=r.children.at(cursor);if(field(row,"m_bDismissed"))continue;const auto type=static_cast<std::uint32_t>(field(row,"m_eNotificationType_bits"));d->completed_steps.push_back(BnwNotificationCleanupStep::expiry_test);if(!bnw_notification_type_end_turn_expired(type,native(field(row,"m_iTurn")),native(d->state.setup.game_turn)))continue;
     auto &flags=d->state.notification_load_transients.players.at(player).slots.at(cursor);if(flags.wait_extra_turn){flags.wait_extra_turn=false;d->waited_slots.push_back(cursor);d->completed_steps.push_back(BnwNotificationCleanupStep::wait_extra_turn_clear);continue;}
     const auto lookup=native(field(row,"m_iLookupIndex"));bool found=false;for(int dismiss=begin;dismiss!=end;dismiss=(dismiss+1)%100){auto &target=r.children.at(dismiss);if(field(target,"m_iLookupIndex")==lookup){field(target,"m_bDismissed")=1;d->completed_steps.push_back(BnwNotificationCleanupStep::dismiss_store);d->batch.removals.push_back({player,lookup,static_cast<std::uint64_t>(dismiss)});d->completed_steps.push_back(BnwNotificationCleanupStep::remove_notification);found=true;break;}}need(found,"Source Dismiss lookup missing in actual native ring");
    }refresh(d->state,player);}
   ++d->owner.operations_;d->owner.epoch_=bnw_notification_epoch(d->state,owner.identity(),rules);d->batch.after_epoch=d->owner.epoch_;
   if(d->batch.before_epoch!=d->batch.after_epoch || !d->batch.removals.empty())apply_bnw_notification_ui_batch(d->state,d->client,rules,d->batch);
   d->active_players_after=bnw_notification_game_turn_active_count(d->state);d->completed_steps.push_back(BnwNotificationCleanupStep::cleanup_complete);out.draft=std::move(d);
  }catch(const std::exception &e){out.blocker=e.what();}return out;}
 static BnwNotificationAddFlagExecution add_flag(const LiveSessionState &s,const BnwNotificationCleanupOwner &owner,const content::RulesDatabase &rules,std::int64_t player,std::uint64_t slot){BnwNotificationAddFlagExecution out;try{validate(s,owner,rules);const auto &r=ring(s,player);need(field(r,"has_notifications")==1 && slot<100 && field(r.children.at(slot),"m_ePlayerID")==player && field(r.children.at(slot),"m_bDismissed")==0,"Source Add flag component needs actual owned notification slot");const auto &p=s.world.all_players->players.at(player);const auto turn=core(p.core,"m_bTurnActive"),automove=core(p.core,"m_bAutoMoves");need((turn==0 || turn==1) && (automove==0 || automove==1),"Source Add flag guard bool unknown");auto d=std::make_unique<BnwNotificationAddFlagDraft>(BnwNotificationAddFlagDraft{s,owner});auto &flag=d->state.notification_load_transients.players.at(player).slots.at(slot).wait_extra_turn;flag=false;if(turn && automove && bnw_notification_type_end_turn_expired(static_cast<std::uint32_t>(field(r.children.at(slot),"m_eNotificationType_bits")),{},native(s.setup.game_turn)))flag=true;need(d->owner.operations_<UINT64_MAX,"Notification operation counter exhausted");++d->owner.operations_;d->owner.epoch_=bnw_notification_epoch(d->state,owner.identity(),rules);out.draft=std::move(d);}catch(const std::exception &e){out.blocker=e.what();}return out;}
};
BnwNotificationCleanupExecution execute_bnw_notification_end_turn_cleanup_draft(const LiveSessionState &s,const BnwNotificationCleanupOwner &owner,const BnwNotificationUiOwner &client,const content::RulesDatabase &rules,std::int64_t player){return BnwNotificationCleanupOperations::cleanup(s,owner,client,rules,player);}
BnwNotificationAddFlagExecution execute_bnw_notification_add_wait_flag_draft(const LiveSessionState &s,const BnwNotificationCleanupOwner &owner,const content::RulesDatabase &rules,std::int64_t player,std::uint64_t slot){return BnwNotificationCleanupOperations::add_flag(s,owner,rules,player,slot);}
} // namespace civ5::runtime
